package com.videokit.spike.e4;
import java.io.*;import java.net.*;import java.nio.charset.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
/** Fixed smart-socket transport + shell-v2. Borrowed streams never close the original socket. */
final class E13JSocket {
 static final int RAW_CAP=65536,WIRE_CAP=70656,MAX_FRAMES=256,FAIL_CAP=256,SERVICE_CAP=2048;static final long QUALIFICATION=10_000_000_000L;
 static final Set<E13JSocket> OWNERS=ConcurrentHashMap.newKeySet();
 interface Hooks{void at(String point)throws Exception;}
 final E4Owned<Socket> socket;final E13JArchive archive;final Thread reader,keeper;final String host,script;final int port;final Hooks hooks;
 volatile boolean allocateEntered,eof,exitSeen,readerBodyReturned,physicalReturned,failed,late,wireOverflow,budgetUnknown;volatile int exit=-999,frames,rawBytes,retainedWire,writesEntered,writesReturned;volatile long chargedWire,incomingWire,intendedTx,deadline;volatile String failure="NONE";final ByteArrayOutputStream stdout=new ByteArrayOutputStream(),stderr=new ByteArrayOutputStream();
 E13JSocket(Path dir,String command){this(dir,command,"127.0.0.1",5037,p->{},null);}
 E13JSocket(Path dir,String command,String h,int p,Hooks k,E13JArchive.IO io){script=command;host=h;port=p;hooks=k;socket=new E4Owned<>("J-original-socket "+h+":"+p,s->{hooks.at("CLOSE_ENTER");s.close();hooks.at("CLOSE_RETURN");});archive=io==null?new E13JArchive(dir):new E13JArchive(dir,io);archive.snapshot=this::audit;reader=new Thread(this::read,"J-original-socket-reader");keeper=new Thread(this::keep,"J-original-socket-custodian");reader.setDaemon(false);keeper.setDaemon(false);OWNERS.add(this);}
 synchronized void fail(String why){failed=true;if(failure.equals("NONE"))failure=why;}
 int allowance(int wanted,boolean exactWrite)throws IOException{long left=WIRE_CAP-chargedWire;if(budgetUnknown||left<=0||exactWrite&&wanted>left){budgetUnknown=true;wireOverflow=true;fail("APPLICATION_IO_BUDGET_UNKNOWN_NO_MORE_IO");archive.requestAudit();throw new IOException("J_BUDGET_STOP_SAME_ORIGINAL_OWNER");}return (int)Math.min(wanted,left);}
 void wire(byte[] b,int n){chargedWire+=n;retainedWire+=n;archive.append(b,n);}
 int readSome(InputStream in,byte[] b,int n)throws Exception{int allowed=allowance(n,false);int r=in.read(b,0,allowed);if(r<0){eof=true;return -1;}incomingWire+=r;wire(b,r);hooks.at("READ_RETURN");return r;}
 byte[] exact(InputStream in,int n,boolean eofAllowed)throws Exception{byte[] out=new byte[n];int at=0;byte[] buffer=new byte[Math.min(4096,Math.max(1,n))];while(at<n){int r=readSome(in,buffer,Math.min(buffer.length,n-at));if(r<0){if(at==0&&eofAllowed)return null;throw new EOFException("I_TRUNCATED_PROTOCOL");}if(r==0)continue;System.arraycopy(buffer,0,out,at,r);at+=r;}return out;}
 void send(OutputStream out,byte[] b)throws Exception{allowance(b.length,true);if(b.length>SERVICE_CAP+4||archive.failed)throw new IOException("J_OUTBOUND_OR_ARCHIVE_BOUND_NO_DEPENDENT_WRITE");intendedTx+=b.length;wire(b,b.length);writesEntered++;out.write(b);out.flush();writesReturned++;hooks.at("WRITE_RETURN");}
 void service(OutputStream out,String s)throws Exception{byte[] b=s.getBytes(StandardCharsets.US_ASCII);if(b.length>SERVICE_CAP)throw new IOException("I_SERVICE_BOUND");ByteArrayOutputStream framed=new ByteArrayOutputStream();framed.write(String.format(java.util.Locale.ROOT,"%04x",b.length).getBytes(StandardCharsets.US_ASCII));framed.write(b);send(out,framed.toByteArray());}
 void status(InputStream in)throws Exception{String s=new String(exact(in,4,false),StandardCharsets.US_ASCII);if(s.equals("OKAY"))return;if(!s.equals("FAIL"))throw new IOException("I_SMART_STATUS");String len=new String(exact(in,4,false),StandardCharsets.US_ASCII);if(!len.matches("[0-9A-Fa-f]{4}"))throw new IOException("I_FAIL_LENGTH");int n=Integer.parseInt(len,16);if(n>FAIL_CAP)throw new IOException("I_FAIL_BOUND");exact(in,n,false);throw new IOException("I_SMART_FAIL");}
 void parse(InputStream in)throws Exception{for(;;){byte[] head=exact(in,5,true);if(head==null){if(!exitSeen)throw new IOException("I_EOF_WITHOUT_EXIT");return;}if(exitSeen)throw new IOException("I_DATA_AFTER_EXIT");if(++frames>MAX_FRAMES)throw new IOException("I_FRAME_LIMIT");int id=head[0]&255;long n=(head[1]&255L)|((head[2]&255L)<<8)|((head[3]&255L)<<16)|((head[4]&255L)<<24);if(id!=1&&id!=2&&id!=3)throw new IOException("I_FRAME_ID");if(n>RAW_CAP||id==3&&n!=1||id!=3&&rawBytes+n>RAW_CAP)throw new IOException("I_FRAME_LENGTH_OR_RAW_CAP");if(id==3){exit=exact(in,1,false)[0]&255;exitSeen=true;continue;}rawBytes+=(int)n;int left=(int)n;byte[] block=new byte[4096];while(left>0){int r=readSome(in,block,Math.min(block.length,left));if(r<0)throw new EOFException("I_TRUNCATED_PAYLOAD");if(r==0)continue;(id==1?stdout:stderr).write(block,0,r);left-=r;}}}
 void drain(InputStream in){byte[] b=new byte[4096];try{while(!budgetUnknown&&readSome(in,b,b.length)>=0){/* charged before every permitted application read; no IO after allowance exhausted */}}catch(Throwable t){fail("ORIGINAL_READ_FAILURE");}}
 void read(){InputStream in=null;try{archive.start("role=J_FIXED_G serial=HA1Q6WXR scriptSha="+E9Record.sha(script.getBytes(StandardCharsets.US_ASCII))+" wireCap="+WIRE_CAP+" metadataReservation=2048\n");allocateEntered=true;socket.allocate(Socket::new);hooks.at("CONNECT_ENTER");socket.original().connect(new InetSocketAddress(host,port),2000);hooks.at("CONNECT_RETURN");in=socket.original().getInputStream();OutputStream out=socket.original().getOutputStream();service(out,"host:transport:HA1Q6WXR");status(in);service(out,"shell,v2,raw:"+script);status(in);send(out,new byte[]{4,0,0,0,0});parse(in);if(exit!=0||stderr.size()!=0)fail("NONZERO_EXIT_OR_STDERR");}catch(Throwable t){fail(t.getClass().getSimpleName()+":"+t.getMessage());if(in!=null&&!eof&&!budgetUnknown)drain(in);}finally{if(allocateEntered&&!budgetUnknown)try{socket.close();}catch(Throwable t){fail("SOCKET_CLOSE_UNKNOWN");}readerBodyReturned=true;archive.end(eof,exit);}}
 void keep(){try{reader.join();while(!archive.resourcesReturned())Thread.sleep(2);if(!budgetUnknown&&!archive.auditFailed&&(!allocateEntered||socket.returned())){physicalReturned=true;OWNERS.remove(this);return;}}catch(Throwable t){fail("KEEPER_UNKNOWN");}for(;;)try{Thread.sleep(1000);}catch(InterruptedException ignored){}}
 byte[] run(long budget)throws Exception{if(budget<=0||budget>QUALIFICATION)throw new IOException("J_QUALIFICATION_BOUND");deadline=System.nanoTime()+budget;reader.start();keeper.start();while(!physicalReturned&&!budgetUnknown&&!archive.auditFailed&&System.nanoTime()<deadline)Thread.sleep(2);if(!physicalReturned){late=System.nanoTime()>=deadline;fail("QUALIFICATION_PENDING_ORIGINAL_RETAINED");archive.requestAudit();throw new IOException("J_PENDING_SAME_ORIGINAL_OWNER");}reader.join();keeper.join();if(System.nanoTime()>=deadline){late=true;fail("LATE_RETURN_QUALIFICATION_FAILED");archive.requestAudit();}if(failed||late||archive.failed||budgetUnknown||!eof||!exitSeen||exit!=0)throw new IOException("J_FAILED_RETURNED "+failure);return stdout.toByteArray();}
 String audit(){boolean l=late||deadline>0&&System.nanoTime()>=deadline;String why=failure.replaceAll("[^A-Za-z0-9_:]","_");if(why.length()>64)why=why.substring(0,64);return "cw="+chargedWire+" in="+incomingWire+" tx="+intendedTx+" we="+writesEntered+" wr="+writesReturned+" rt="+retainedWire+" off="+archive.offered+" disk="+archive.written+" rawQuota="+rawBytes+" frames="+frames+" eof="+eof+" exitSeen="+exitSeen+" exit="+exit+" failed="+(failed||archive.failed)+" late="+l+" qualification="+(failed||archive.failed||l?"FAILED":"SNAPSHOT_NOT_FINAL")+" budgetUnknown="+budgetUnknown+" readerBody="+readerBodyReturned+" readerAlive="+reader.isAlive()+" socketReturned="+socket.returned()+" writerAlive="+(archive.writer!=null&&archive.writer.isAlive())+" physical="+physicalReturned+" why="+why+" auditOwnClose=UNPROVEN";}
 String facts(){return "eof="+eof+" exitSeen="+exitSeen+" exit="+exit+" readerAlive="+reader.isAlive()+" socketReturned="+socket.returned()+" physicalReturned="+physicalReturned+" frames="+frames+" rawBytes="+rawBytes+" retainedWire="+retainedWire+" chargedWire="+chargedWire+" incomingWire="+incomingWire+" intendedTx="+intendedTx+" writesEntered="+writesEntered+" writesReturned="+writesReturned+" incomplete="+(wireOverflow||archive.failed)+" failed="+failed+" late="+late;}
}
